/// <summary>
/// Extension class for SalesInvoiceDP to customize sales invoice data processing for AVARUM.
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDP))]
final class AVARUMSalesInvoiceDPCls_Extension
{
}

Method.Source:
/// <summary>
/// Populates the temporary sales invoice record with data from the provided parameters.
/// </summary>
/// <param name = "_custInvoiceJour">Customer Invoice Journal record </param>
/// <param name = "_custInvoiceTrans">Customer Invoice Transaction record </param>
/// <param name = "_taxSpec">Tax Specification record </param>
/// <param name = "_custPaymSchedLine">Customer Payment Schedule Line record </param>
/// <param name = "_prepaymentCustTrans">Prepayment Customer Transaction record </param>
/// <param name = "_prepaymentTaxTrans">Prepayment Tax Transaction record </param>
protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
    CustInvoiceTrans _custInvoiceTrans,
    TaxSpec _taxSpec,
    CustPaymSchedLine _custPaymSchedLine,
    CustTrans _prepaymentCustTrans,
    TaxTrans _prepaymentTaxTrans)
{
    next populateSalesInvoiceTmp
    (
        _custInvoiceJour,
        _custInvoiceTrans,
        _taxSpec,
        _custPaymSchedLine,
        _prepaymentCustTrans,
        _prepaymentTaxTrans
    );

    // Custom logic to handle AVARUM specific requirements        
    SalesLine salesLine = _custInvoiceTrans.salesLine();
    salesInvoiceTmp.AVARUMSalesLineRefRecId = salesLine.RecId;
}
